abstract class Request<TResult> {
  declare readonly __result: TResult;
}
type ResultOf<R> = R extends Request<infer T> ? T : never;
type RequestClass<R> = abstract new (...args: never[]) => R;

class ClassBus {
  readonly #handlers = new Map<unknown, (request: never) => unknown>();

  register<R extends Request<unknown>>(type: RequestClass<R>, handler: (request: R) => ResultOf<R>): this {
    this.#handlers.set(type, handler);
    return this;
  }

  execute<T>(request: Request<T>): T {
    const handler = this.#handlers.get(request.constructor);
    if (!handler) throw new Error(`no handler for ${request.constructor.name}`);
    return (handler as (request: Request<T>) => T)(request);
  }
}

class GetBalance extends Request<number> {
  constructor(readonly accountId: string) {
