const processed = new Map<string, string>();
let charges = 0;

function payInvoice(command: { commandId: string; invoice: string; kobo: number }): string {
  const earlier = processed.get(command.commandId);
  if (earlier !== undefined) return earlier;
  charges++;
  const receipt = `receipt ${charges}: ${command.invoice} ₦${command.kobo / 100}`;
  processed.set(command.commandId, receipt);
  return receipt;
}

const retry = { commandId: "cmd-81f", invoice: "INV-9", kobo: 4_500_000 };
console.log(payInvoice(retry));
console.log(payInvoice(retry));
console.log(payInvoice({ ...retry, commandId: "cmd-82a" }));
console.log("charges:", charges);
